def build():
    rows=[]
    for idx,(label,category,group,title,story,goal,city,state,doc) in enumerate(ROWS,1):
        docs=[]
        if doc:
            kind,doc_title,content=doc
            docs=[{'doc_type':kind,'title':f'Synthetic {doc_title}','content':f'[Synthetic document]\n{content}'}]
        rows.append({'case_id':f'IND-{idx:03d}','ground_truth':label,'scenario_group':group,'synthetic':True,'input':{
            'title':title,'category':category,'story':story,'goal_amount':goal,'beneficiary_name':None,
            'beneficiary_type':'SELF','city':city,'state':state,'documents':docs}})
    assert len(rows)==100
    assert len({r['input']['story'] for r in rows})==100
    assert {label:sum(r['ground_truth']==label for r in rows) for label in ('legitimate','fraudulent','borderline')}=={'legitimate':40,'fraudulent':40,'borderline':20}
    return rows

if __name__=='__main__':
    OUT.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in build()),encoding='utf-8')
    print(f'Wrote {len(build())} scenarios to {OUT}')
